export const createCacheablePrompt = (
  playData: Play,
  showContext: ShowContext | null,
  recentInsights: Insight[]
): Message[] => [
  {
    role: "system",
    content: STATIC_SYSTEM_PROMPT,  // ~8,500 tokens
    cache_control: { type: "ephemeral" }  // Anthropic caches
  },
  {
    role: "system",
    content: buildDynamicPrompt({
      currentTime: new Date(),
      showContext,
      recentInsights: recentInsights.slice(-10)
    })  // ~1,500 tokens, not cached
  },
  {
    role: "user",
    content: buildPlayMessage(playData)  // ~150 tokens
  }
]
